// textNode.js — rebuilt with BaseNode abstraction

import { useState } from 'react';
import { BaseNode, NodeTextArea } from './BaseNode';

const TEXT_HANDLES = {
  outputs: [{ id: 'output', label: 'text' }],
};

export const TextNode = ({ id, data }) => {
  const [currText, setCurrText] = useState(data?.text || '{{input}}');

  return (
    <BaseNode
      id={id}
      label="Text"
      color="#0ea5e9"
      icon="T"
      outputs={TEXT_HANDLES.outputs}
    >
      <NodeTextArea
        label="Content"
        value={currText}
        onChange={e => setCurrText(e.target.value)}
        placeholder="Use {{variable}} syntax..."
        rows={3}
      />
    </BaseNode>
  );
};
